export const tools = [
  {
    name: 'current_time',
    description: 'Return the current date and time for an IANA time zone (default UTC).',
    parameters: {
      type: 'object',
      properties: { timeZone: { type: 'string', description: "e.g. Asia/Bangkok" } },
      required: [],
    },
    async handler(args) {
      const zone = typeof args.timeZone === 'string' && args.timeZone ? args.timeZone : 'UTC';
      const now = new Date();
      const formatted = new Intl.DateTimeFormat('en-CA', {
        timeZone: zone,
        dateStyle: 'full',
        timeStyle: 'long',
      }).format(now);
      return formatted + ' (' + zone + ')';
    },
  },
];
